"""Day 24：评测数据集版本、校验与可复现性。

统一字段：id / category / input / expected / evaluator_names / metadata
- Schema 校验：pydantic，错误能定位到样本 ID 与字段路径
- 规范化哈希：JSON 键排序后计算 SHA-256，同内容同哈希
- 运行快照：dataset_hash / git_commit / provider config / seed / start_time
"""

from __future__ import annotations

import hashlib
import json
import subprocess
from datetime import datetime
from typing import Any, Optional

from pydantic import BaseModel, Field, ValidationError, field_validator

# 数据集 Schema 版本号
SCHEMA_VERSION = "1.0"


class DatasetRecord(BaseModel):
    """评测数据集的一行记录（统一字段）。"""

    id: str = Field(min_length=1)
    category: str = Field(min_length=1)
    input: str = Field(min_length=1)
    expected: str
    evaluator_names: list[str] = Field(default_factory=list)
    metadata: dict[str, Any] = Field(default_factory=dict)

    @field_validator("input")
    @classmethod
    def input_not_blank(cls, value: str) -> str:
        if not value.strip():
            raise ValueError("input 不能为空")
        return value


def normalize_record(record: dict[str, Any]) -> str:
    """规范化 JSON：键排序 + 紧凑分隔符，保证同内容同字符串（键顺序无关）。"""
    return json.dumps(
        record,
        sort_keys=True,      # 键按字母排序 → 键顺序变化不影响结果
        ensure_ascii=False,  # 保留中文，可读
        separators=(",", ":"),
    )


def record_hash(record: dict[str, Any]) -> str:
    """单条记录的 SHA-256。"""
    return hashlib.sha256(normalize_record(record).encode("utf-8")).hexdigest()


def dataset_hash(records: list[dict[str, Any]]) -> str:
    """整份数据集的 SHA-256：所有记录规范化后拼接再哈希。"""
    payload = "\n".join(normalize_record(record) for record in records)
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()


def validate_dataset(records: list[dict[str, Any]]) -> list[str]:
    """校验数据集，返回可读错误列表（带样本 ID 与字段路径）。"""
    errors: list[str] = []
    for index, record in enumerate(records, start=1):
        record_id = record.get("id", f"<第{index}行>")
        try:
            DatasetRecord.model_validate(record)
        except ValidationError as exc:
            for error in exc.errors():
                field_path = ".".join(str(part) for part in error["loc"])
                errors.append(
                    f"record #{index} (id={record_id})："
                    f"字段 [{field_path}] 校验失败：{error['msg']}"
                )
    return errors


def load_dataset(file_path: str) -> list[dict[str, Any]]:
    """读取 JSONL 数据集并返回记录列表（Schema 校验交给 validate_dataset）。"""
    from evalhub_core.loader import load_jsonl

    return load_jsonl(file_path)


def git_commit_sha() -> str:
    """当前仓库 HEAD 的 commit SHA；非 git 仓库时返回 unknown。"""
    try:
        result = subprocess.run(
            ["git", "rev-parse", "HEAD"],
            capture_output=True,
            text=True,
            timeout=5,
        )
        return result.stdout.strip() or "unknown"
    except Exception:
        return "unknown"


def build_run_manifest(
    records: list[dict[str, Any]],
    provider: Optional[str] = None,
    model: Optional[str] = None,
    seed: int = 42,
    start_time: Optional[str] = None,
) -> dict[str, Any]:
    """运行参数快照：dataset_hash、git_commit、provider config、seed、开始时间。"""
    return {
        "schema_version": SCHEMA_VERSION,
        "dataset_hash": dataset_hash(records),
        "git_commit": git_commit_sha(),
        "provider": provider,
        "model": model,
        "seed": seed,
        "start_time": start_time or datetime.now().isoformat(timespec="seconds"),
    }

"""DeepSeek 厂商响应 → 统一 LLMResponse 的映射（Day 21）。"""

import json

from evalhub_core.schemas import LLMResponse, TokenUsage


class InvalidJSONResponse(Exception):
    """模型返回的内容不是合法 JSON 对象。"""


def map_deepseek_response(payload: dict, latency_ms: float) -> LLMResponse:
    """把 DeepSeek chat completions 原始响应映射为统一 LLMResponse。

    payload 两种形态：
    - 成功：{"choices": [{"message": {"content": "..."}}], "usage": {...}}
    - 失败：{"error": {"message": "...", "type": "..."}}
    """
    if "error" in payload:
        return LLMResponse(
            content=None,
            latency_ms=latency_ms,
            error_type="provider_error",
            token_usage=None,
        )

    content = payload["choices"][0]["message"]["content"]

    token_usage = None
    usage = payload.get("usage")
    if usage:
        token_usage = TokenUsage(
            prompt_tokens=usage["prompt_tokens"],
            completion_tokens=usage["completion_tokens"],
            total_tokens=usage["total_tokens"],
        )

    return LLMResponse(
        content=content,
        latency_ms=latency_ms,
        error_type=None,
        token_usage=token_usage,
    )


def extract_json_object(content: str) -> dict:
    """从模型输出中提取 JSON 对象；失败时抛出结构化错误。"""
    try:
        data = json.loads(content)
    except json.JSONDecodeError as exc:
        raise InvalidJSONResponse(f"模型返回的内容不是合法 JSON：{exc.msg}") from exc

    if not isinstance(data, dict):
        raise InvalidJSONResponse("模型返回的 JSON 不是对象")

    return data

"""Day 25：评分器接口与实现（BaseEvaluator / ExactMatchEvaluator / JsonSchemaEvaluator）。"""

import json
from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from typing import Dict

from evalhub_core.evaluator import exact_match


@dataclass
class EvaluationItem:
    """一条评测结果（失败案例保留 input / expected / actual / reason）。"""

    id: str
    category: str
    input: str
    expected: str
    actual: str
    scores: Dict[str, float] = field(default_factory=dict)
    passed: bool = True
    reason: str | None = None


class BaseEvaluator(ABC):
    """所有评分器的统一接口。"""

    name: str = "base"

    @abstractmethod
    def evaluate(self, item: EvaluationItem) -> EvaluationItem:
        """对一条记录打分，把分数写进 item.scores。"""
        raise NotImplementedError


class ExactMatchEvaluator(BaseEvaluator):
    """正确性评分器：预测与标准答案完全一致（复用 Day 5 的 exact_match）。"""

    name = "exact_match"

    def evaluate(self, item: EvaluationItem) -> EvaluationItem:
        matched = exact_match(item.actual, item.expected)
        item.scores["accuracy"] = 1.0 if matched else 0.0
        if not matched:
            item.passed = False
            item.reason = (
                f"exact_match 不匹配：actual={item.actual!r}, expected={item.expected!r}"
            )
        return item


class JsonSchemaEvaluator(BaseEvaluator):
    """格式评分器：输出是否为合法 JSON 对象（与内容正确性分开，验收③）。"""

    name = "json_schema"

    def evaluate(self, item: EvaluationItem) -> EvaluationItem:
        try:
            data = json.loads(item.actual)
            valid = isinstance(data, dict)
            item.scores["format_rate"] = 1.0 if valid else 0.0
            if not valid:
                item.reason = "输出是 JSON 但不是对象"
        except json.JSONDecodeError as exc:
            item.scores["format_rate"] = 0.0
            item.reason = f"非法 JSON：{exc.msg}"
        return item


class EvaluatorRegistry:
    """评分器注册表：新增评分器只注册一行（对应 Day 22 的工厂思想）。"""

    _registry: Dict[str, BaseEvaluator] = {}

    @classmethod
    def register(cls, evaluator: BaseEvaluator) -> None:
        cls._registry[evaluator.name] = evaluator

    @classmethod
    def get(cls, name: str) -> BaseEvaluator:
        if name not in cls._registry:
            raise ValueError(f"未知评分器：{name}，可用：{sorted(cls._registry)}")
        return cls._registry[name]

    @classmethod
    def names(cls) -> list[str]:
        return sorted(cls._registry)


# 内置注册：新增评分器就在这里加一行
EvaluatorRegistry.register(ExactMatchEvaluator())
EvaluatorRegistry.register(JsonSchemaEvaluator())

"""EvalHub 最小健康检查。"""

from __future__ import annotations

import json


def get_health() -> dict[str, str]:
    """返回不依赖数据库和外部 API 的健康状态。"""

    return {
        "status": "ok",
        "service": "evalhub",
    }


def main() -> int:
    """将健康状态输出为 JSON。"""

    print(
        json.dumps(
            get_health(),
            ensure_ascii=False,
        )
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Day 26：任务状态机（pending/running/completed/completed_with_errors/failed/cancelled）。"""

from typing import Dict, Set

# 合法迁移表：当前状态 -> 允许的下一状态集合
ALLOWED_TRANSITIONS: Dict[str, Set[str]] = {
    "pending": {"running", "cancelled"},
    "running": {"completed", "completed_with_errors", "failed", "cancelled"},
    "completed": set(),
    "completed_with_errors": set(),
    "failed": set(),
    "cancelled": set(),
}

TERMINAL_STATES = {"completed", "completed_with_errors", "failed", "cancelled"}


def can_transition(current: str, next_state: str) -> bool:
    return next_state in ALLOWED_TRANSITIONS.get(current, set())


def transition(current: str, next_state: str) -> str:
    """执行迁移；非法迁移抛 ValueError。"""
    if not can_transition(current, next_state):
        raise ValueError(
            f"非法状态迁移：{current} -> {next_state}；"
            f"允许：{sorted(ALLOWED_TRANSITIONS.get(current, set())) or '无（终态）'}"
        )
    return next_state

"""Day 22：统一 LLM Provider 抽象 + ProviderFactory。

设计（对应实战题 3 的依赖图）：
- BaseLLMProvider 是所有 Provider 的统一接口（依赖倒置：业务层只依赖这个抽象）
- DeepSeekProvider 真实调用 DeepSeek（复用 Day 21 的响应映射）
- MockLLMProvider 不联网，响应模型与真实完全一致（都返回 LLMResponse）
- ProviderFactory 用注册表 + 配置创建实例；新增 Provider 只改注册表和配置
"""

import os
import time
from abc import ABC, abstractmethod
from typing import Dict, Type

import httpx

from evalhub_core.deepseek import map_deepseek_response
from evalhub_core.llm_config import LLMConfig
from evalhub_core.schemas import LLMRequest, LLMResponse


class BaseLLMProvider(ABC):
    """所有模型 Provider 的统一接口（业务层只依赖它，不依赖任何厂商 SDK）。"""

    def __init__(self, config: LLMConfig) -> None:
        self.config = config

    @abstractmethod
    def generate(self, request: LLMRequest) -> LLMResponse:
        """根据请求生成响应；所有 Provider 都必须返回 LLMResponse。"""
        raise NotImplementedError


class DeepSeekProvider(BaseLLMProvider):
    """真实调用 DeepSeek API 的 Provider（复用 Day 21 的 map_deepseek_response）。"""

    def generate(self, request: LLMRequest) -> LLMResponse:
        api_key = os.environ.get(self.config.api_key_env, "")
        if not api_key:
            raise RuntimeError(
                f"环境变量 {self.config.api_key_env} 未配置，无法调用 DeepSeek"
            )

        payload = {
            "model": self.config.model,
            "messages": [
                {"role": "system", "content": "你是评测数据助手，只输出 JSON 对象。"},
                {"role": "user", "content": request.input},
            ],
            "max_tokens": self.config.max_tokens,
            "temperature": request.temperature,
            "response_format": {"type": "json_object"},
        }
        headers = {
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
        }

        started = time.perf_counter()
        with httpx.Client(
            base_url=self.config.base_url,
            timeout=self.config.timeout,
        ) as client:
            response = client.post("/chat/completions", json=payload, headers=headers)
        latency_ms = (time.perf_counter() - started) * 1000

        return map_deepseek_response(response.json(), latency_ms=latency_ms)


class MockLLMProvider(BaseLLMProvider):
    """不联网的 Mock Provider：success / timeout / 429 / invalid_json。

    响应模型与 DeepSeekProvider 完全一致（都返回 LLMResponse），
    只是不发起真实网络请求——这就是"Mock 与真实响应同模型"。
    """

    def generate(self, request: LLMRequest) -> LLMResponse:
        from evalhub_core.provider import MockProvider

        return MockProvider(behavior=self.config.behavior).generate(request.input)


class DummyProvider(BaseLLMProvider):
    """实战题 1：新增 Provider 只改注册表和配置即可使用，业务层零改动。"""

    def generate(self, request: LLMRequest) -> LLMResponse:
        return LLMResponse(
            content=f"dummy: {request.input}",
            latency_ms=1.0,
            error_type=None,
            token_usage=None,
        )


class ProviderFactory:
    """按配置创建 Provider 实例；注册表驱动，未知 provider 给出可读错误。"""

    _registry: Dict[str, Type[BaseLLMProvider]] = {}

    @classmethod
    def register(cls, name: str, provider_cls: Type[BaseLLMProvider]) -> None:
        cls._registry[name] = provider_cls

    @classmethod
    def create(cls, config: LLMConfig) -> BaseLLMProvider:
        provider_cls = cls._registry.get(config.provider)
        if provider_cls is None:
            raise ValueError(
                f"未知 provider：{config.provider}，可用选项：{sorted(cls._registry)}"
            )
        return provider_cls(config)

    @classmethod
    def available(cls) -> list[str]:
        return sorted(cls._registry)


# 内置注册：新增 Provider 就在这里加一行
ProviderFactory.register("deepseek", DeepSeekProvider)
ProviderFactory.register("mock", MockLLMProvider)
ProviderFactory.register("dummy", DummyProvider)

import json
from pathlib import Path
from typing import Any


class DatasetFormatError(Exception):
    """当 JSONL 数据集格式不符合要求时抛出。"""


REQUIRED_FIELDS = ("id", "input", "expected", "category")


def load_jsonl(file_path: str) -> list[dict[str, Any]]:
    """读取并验证 EvalHub JSONL 数据集。"""

    path = Path(file_path)

    if not path.exists():
        raise FileNotFoundError(
            f"数据集文件不存在：{path}\n"
            "请确认终端位于项目根目录，并检查文件路径。"
        )

    if not path.is_file():
        raise DatasetFormatError(
            f"指定的路径不是文件：{path}"
        )

    records: list[dict[str, Any]] = []

    try:
        with path.open("r", encoding="utf-8") as file:
            for line_number, line in enumerate(file, start=1):
                line = line.strip()

                if not line:
                    continue

                try:
                    record = json.loads(line)
                except json.JSONDecodeError as exc:
                    raise DatasetFormatError(
                        f"第 {line_number} 行不是合法的 JSON：{exc.msg}\n"
                        f"文件位置：{path}"
                    ) from exc

                if not isinstance(record, dict):
                    raise DatasetFormatError(
                        f"第 {line_number} 行必须是 JSON 对象，"
                        f"当前类型为：{type(record).__name__}"
                    )

                for field_name in REQUIRED_FIELDS:
                    if field_name not in record:
                        raise DatasetFormatError(
                            f"第 {line_number} 行缺少 {field_name} 字段。"
                        )

                if not isinstance(record["id"], str):
                    raise DatasetFormatError(
                        f"第 {line_number} 行的 id 必须是字符串。"
                    )

                if not isinstance(record["input"], str):
                    raise DatasetFormatError(
                        f"第 {line_number} 行的 input 必须是字符串。"
                    )

                if not isinstance(record["expected"], str):
                    raise DatasetFormatError(
                        f"第 {line_number} 行的 expected 必须是字符串。"
                    )

                if not isinstance(record["category"], str):
                    raise DatasetFormatError(
                        f"第 {line_number} 行的 category 必须是字符串。"
                    )

                records.append(record)

    except UnicodeDecodeError as exc:
        raise DatasetFormatError(
            f"数据集不是有效的 UTF-8 编码：{path}"
        ) from exc

    if not records:
        raise DatasetFormatError(
            f"数据集为空：{path}"
        )

    return records

"""Day 25：聚合指标（成功率/准确率/格式率/均值/P50/P95/Token/成本）与分组。"""

from typing import Any, Dict, List, Optional

from evalhub_core.evaluators import EvaluationItem


def percentile(values: List[float], p: float) -> float:
    """百分位数（p 为 0~100）；空列表返回 0.0。"""
    if not values:
        return 0.0
    sorted_values = sorted(values)
    index = (len(sorted_values) - 1) * p / 100
    lower = int(index)
    upper = min(lower + 1, len(sorted_values) - 1)
    frac = index - lower
    return sorted_values[lower] * (1 - frac) + sorted_values[upper] * frac


def aggregate(items: List[EvaluationItem], latencies: Optional[List[float]] = None) -> Dict[str, Any]:
    """汇总全部评测结果的指标。"""
    total = len(items)
    passed = sum(1 for item in items if item.passed)
    accuracy = sum(item.scores.get("accuracy", 0.0) for item in items) / total if total else 0.0
    format_rate = sum(item.scores.get("format_rate", 0.0) for item in items) / total if total else 0.0
    latency_values = latencies or []
    return {
        "total": total,
        "success_rate": passed / total if total else 0.0,
        "accuracy": accuracy,
        "format_rate": format_rate,
        "latency_ms": {
            "mean": sum(latency_values) / len(latency_values) if latency_values else 0.0,
            "p50": percentile(latency_values, 50),
            "p95": percentile(latency_values, 95),
        },
    }


def token_cost(tokens: int, price_per_million: float) -> float:
    """Token 成本：每百万 token 单价 × token 数 / 1e6；价格可配置（验收④）。"""
    return tokens * price_per_million / 1_000_000


def group_by_category(items: List[EvaluationItem]) -> Dict[str, Dict[str, Any]]:
    """按 category 分组聚合。"""
    groups: Dict[str, List[EvaluationItem]] = {}
    for item in items:
        groups.setdefault(item.category, []).append(item)
    return {category: aggregate(group) for category, group in groups.items()}

from abc import ABC, abstractmethod
from typing import List

from evalhub_core.schemas import LLMResponse


class BaseProvider(ABC):
    """所有模型Provider都必须遵守的统一接口。"""

    @abstractmethod
    def generate(self, prompt: str) -> LLMResponse:
        """
        根据prompt生成模型响应。

        所有Provider都必须返回LLMResponse。
        """

        raise NotImplementedError


class MockProvider(BaseProvider):
    """不调用真实API，用于模拟不同模型响应。"""

    SUPPORTED_BEHAVIORS = {
        "success",
        "timeout",
        "429",
        "invalid_json",
    }

    def __init__(self, behavior: str = "success"):
        if behavior not in self.SUPPORTED_BEHAVIORS:
            raise ValueError(
                f"不支持的Mock行为：{behavior}，"
                f"可选值为：{sorted(self.SUPPORTED_BEHAVIORS)}"
            )

        self.behavior = behavior

    def generate(self, prompt: str) -> LLMResponse:
        """根据指定行为返回模拟响应。"""

        if self.behavior == "success":
            return LLMResponse(
                content=f"Mock response: {prompt}",
                latency_ms=10,
                error_type=None,
                token_usage={
                    "prompt_tokens": 8,
                    "completion_tokens": 10,
                    "total_tokens": 18,
                },
            )

        if self.behavior == "timeout":
            return LLMResponse(
                content="",
                latency_ms=3000,
                error_type="timeout",
                token_usage=None,
            )

        if self.behavior == "429":
            return LLMResponse(
                content="",
                latency_ms=100,
                error_type="rate_limit",
                token_usage=None,
            )

        # invalid_json表示：
        # 模型调用本身成功，所以error_type为None；
        # 但是模型返回的content不是合法JSON。
        return LLMResponse(
            content='{"answer": "缺少右括号"',
            latency_ms=20,
            error_type=None,
            token_usage={
                "prompt_tokens": 8,
                "completion_tokens": 10,
                "total_tokens": 18,
            },
        )


class SequenceMockProvider(BaseProvider):
    """按照预设顺序返回不同结果。"""

    def __init__(self, behaviors: List[str]):
        if not behaviors:
            raise ValueError("behaviors不能为空")

        unsupported_behaviors = [
            behavior
            for behavior in behaviors
            if behavior not in MockProvider.SUPPORTED_BEHAVIORS
        ]

        if unsupported_behaviors:
            raise ValueError(
                f"存在不支持的行为：{unsupported_behaviors}"
            )

        self.behaviors = behaviors
        self.current_index = 0

    def generate(self, prompt: str) -> LLMResponse:
        """
        按照behaviors中的顺序返回响应。

        当调用次数超过行为数量后，
        继续使用最后一个行为。
        """

        if self.current_index >= len(self.behaviors):
            behavior = self.behaviors[-1]
        else:
            behavior = self.behaviors[self.current_index]
            self.current_index += 1

        provider = MockProvider(behavior=behavior)

        return provider.generate(prompt)

"""Day 23：可重试错误分类 + 指数退避重试策略（纯函数，可独立测试）。

验收映射：
- 429（限流）、500/502/503（服务端错误）→ 可重试
- 400/401/403/404/422（客户端错误）→ 不重试，立即失败
"""

import random
from dataclasses import dataclass
from typing import Optional

# 可重试：限流 + 服务端错误
RETRYABLE_STATUS = {429, 500, 502, 503}
# 不可重试：客户端错误（400/401/403/404/422 等）
NON_RETRYABLE_STATUS = {400, 401, 403, 404, 422}


def should_retry(status_code: int) -> bool:
    """该状态码是否值得重试。"""
    return status_code in RETRYABLE_STATUS


def parse_retry_after(header_value: Optional[str]) -> Optional[float]:
    """解析 Retry-After 响应头（秒数形式）；HTTP 日期形式或缺失时返回 None。"""
    if not header_value:
        return None
    value = header_value.strip()
    try:
        return float(value)
    except ValueError:
        # HTTP 日期形式（如 Wed, 21 Oct 2026 07:28:00 GMT）不处理，走默认退避
        return None


@dataclass
class RetryPolicy:
    """指数退避 + 随机抖动（+ Retry-After 优先）的重试策略。"""

    max_attempts: int = 3
    base_delay: float = 0.2
    max_delay: float = 2.0
    jitter: bool = True

    def delay_for(self, attempt: int, retry_after: Optional[float] = None) -> float:
        """第 attempt 次重试前等待的秒数（attempt 从 1 开始）。

        Retry-After 优先；否则 base_delay * 2^(attempt-1)，封顶 max_delay，
        开启抖动时再乘以 0.5~1.5 的随机系数。
        """
        if retry_after is not None:
            return min(retry_after, self.max_delay)
        delay = min(self.base_delay * (2 ** (attempt - 1)), self.max_delay)
        if self.jitter:
            delay *= random.uniform(0.5, 1.5)
        return delay
